import {geometry,worldGeometry,pathData,connections,nearestSnap,snapToEndpoint,norm,bounds,validateProject,billOfMaterials,demoProject,rad,transform} from './geometry.js';
import {selectionRect,boxedSelection} from './selection.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORAGE_KEY=new URLSearchParams(location.search).has('qa')?'rail-studio-qa-v1':'rail-studio-project-v1';
let catalog,byId,project;const selected=new Set();let brand='KATO',scale='N',category='直轨',placing=null,tool='select',history=[],future=[],view={x:-150,y:-150,w:2100,h:1300},pointer={x:800,y:400},ghost=null,gesture=null,space=false,cache=null,toastTimer,saveTimer;
const clone=o=>JSON.parse(JSON.stringify(o)), uid=()=>globalThis.crypto?.randomUUID?.()||'p'+Date.now().toString(36)+Math.random().toString(36).slice(2), svg=$('#canvas'),scene=$('#scene');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function modal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function persist(){clearTimeout(saveTimer);$('#save-status').textContent='正在保存…';saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(project));$('#save-status').textContent='已保存到本机';}catch{$('#save-status').textContent='本机存储不可用，请保存文件';}},200);}
function record(){history.push(clone(project));if(history.length>80)history.shift();future=[];}
function changed(){cache=null;persist();render();}
function undo(){if(!history.length)return;future.push(clone(project));project=history.pop();selected.clear();changed();}
function redo(){if(!future.length)return;history.push(clone(project));project=future.pop();selected.clear();changed();}
function getConnections(){return cache||(cache=connections(project.pieces,byId));}
function fit(){const r=svg.getBoundingClientRect(),ratio=r.width/Math.max(r.height,1),w=project.board.width+240,h=project.board.height+270;view.w=Math.max(w,h*ratio);view.h=view.w/ratio;view.x=(project.board.width-view.w)/2;view.y=(project.board.height-view.h)/2;renderCanvas();}
function point(event){const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const c=p.matrixTransform(svg.getScreenCTM().inverse());return {x:c.x,y:c.y};}
function zoom(factor,anchor){const p=anchor||{x:view.x+view.w/2,y:view.y+view.h/2},nw=Math.max(100,Math.min(100000,view.w*factor)),f=nw/view.w;view={x:p.x-(p.x-view.x)*f,y:p.y-(p.y-view.y)*f,w:nw,h:view.h*f};renderCanvas();}
function offset(points,d){return points.map((p,i)=>{const a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],l=Math.hypot(b.x-a.x,b.y-a.y)||1;return {x:p.x-(b.y-a.y)/l*d,y:p.y+(b.x-a.x)/l*d};});}
function trackMarkup(part,piece,options={}){const g=worldGeometry(part,piece),isSelected=selected.has(piece.id)&&!options.export,base=part.brand==='KATO'?'#385f4c':'#467ea4',color=isSelected?'#d88b3e':base,gauge=part.scale==='HO'?16.5:9;let s='';
 if(part.geometry.type==='turntable'){const c=transform(part.geometry.center,piece);s+=`<circle cx="${c.x}" cy="${c.y}" r="${part.geometry.outerRadius}" fill="#e7ece7" stroke="#a3b5a7" stroke-width="2"/>`;}
 for(const path of g.paths){const d=pathData(path.points);s+=`<path d="${d}" fill="none" stroke="${isSelected?'#eacda5':'#d2dbd2'}" stroke-width="${gauge+13}" stroke-linecap="butt"/>`;
 // Ties are regular along the sampled centerline, independent of the zoom level.
 for(let i=0,carry=0;i<path.points.length-1;i++){const a=path.points[i],b=path.points[i+1],l=Math.hypot(b.x-a.x,b.y-a.y),dx=(b.x-a.x)/l,dy=(b.y-a.y)/l;for(let t=carry;t<l;t+=7){const x=a.x+dx*t,y=a.y+dy*t;s+=`<path d="M${x-dy*(gauge/2+3)} ${y+dx*(gauge/2+3)}L${x+dy*(gauge/2+3)} ${y-dx*(gauge/2+3)}" stroke="${isSelected?'#c9a571':'#a4b5a4'}" stroke-width="2.5"/>`;}carry=(carry-l)%7;if(carry<0)carry+=7;}
 for(const d1 of [-gauge/2,gauge/2])s+=`<path d="${pathData(offset(path.points,d1))}" fill="none" stroke="${color}" stroke-width="1.8"/>`;
 }
 if(part.geometry.type==='buffer'){const p=g.paths[0].points.at(-1);s+=`<circle cx="${p.x}" cy="${p.y}" r="7" fill="#965b48"/>`;}
 if($('#labels-toggle').checked||options.labels){const mid=g.paths[0]?.points[Math.floor(g.paths[0].points.length/2)];if(mid)s+=`<text x="${mid.x}" y="${mid.y-18}" class="track-label" font-size="11" fill="#58705f">${esc(part.sku)}</text>`;}
 return `<g ${options.export?'':`data-piece="${esc(piece.id)}" class="track"`} opacity="${options.ghost?.6:1}">${s}${!options.export?g.paths.map(p=>`<path d="${pathData(p.points)}" fill="none" stroke="transparent" stroke-width="${Math.max(24,view.w/svg.clientWidth*12)}"/>`).join(''):''}</g>`;
}
function thumb(part){if(!part.geometry.type)return '<svg viewBox="0 0 100 60"><text x="50" y="37" text-anchor="middle" font-size="24" fill="#a1aca5">⌁</text></svg>';const g=geometry(part),pts=g.paths.flatMap(p=>p.points),minx=Math.min(...pts.map(p=>p.x)),maxx=Math.max(...pts.map(p=>p.x)),miny=Math.min(...pts.map(p=>p.y)),maxy=Math.max(...pts.map(p=>p.y));const w=Math.max(40,maxx-minx),h=Math.max(35,maxy-miny),pad=Math.max(w,h)*.15;return `<svg viewBox="${minx-pad} ${miny-pad} ${w+2*pad} ${h+2*pad}">${g.paths.map(p=>`<path d="${pathData(p.points)}" fill="none" stroke="${part.brand==='KATO'?'#547760':'#6489aa'}" stroke-width="${Math.max(w,h)/35}"/>`).join('')}</svg>`;}
function filtered(){const query=$('#search').value.trim().toLowerCase();return catalog.parts.filter(p=>p.brand===brand&&p.scale===scale&&(category==='全部'||p.category===category)&&(!$('#usable-only').checked||p.geometry.type)&&(!query||(p.sku+' '+p.name+' '+p.label+' '+p.category).toLowerCase().includes(query)));}
function renderLibrary(){const cats=['全部','直轨','弯轨','道岔','复线','高架 / 桥梁','有轨电车','特殊'];$('#categories').innerHTML=cats.map(c=>`<button data-category="${esc(c)}" class="${category===c?'active':''}">${esc(c)}</button>`).join('');const list=filtered();$('#library-count').textContent=`${list.length} 种轨道`;$('#system-label').textContent=brand==='TOMIX'?'FINE TRACK':'UNITRACK';$$('[data-brand]').forEach(b=>b.classList.toggle('active',b.dataset.brand===brand));$('#parts-list').innerHTML=list.length?list.map(p=>`<button class="part-card ${placing?.partId===p.id?'active':''} ${p.status==='pending'?'pending':''}" data-part="${esc(p.id)}" title="${esc(p.name)}${p.status==='approximate'?' · 名义尺寸示意':''}">${thumb(p)}<span><strong>${esc(p.label)}</strong><small>${esc(p.sku)}${p.status==='pending'?' · 待核实几何':p.status==='approximate'?' · 示意尺寸':p.status==='library'?' · 开源参数':''}</small></span><span class="plus">${p.status==='pending'?'↗':'＋'}</span></button>`).join(''):'<div class="no-results">没有匹配的轨道。<br>试试其他型号或系列。</div>';}
function renderCanvas(){if(!project)return;svg.setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);const w=project.board.width,h=project.board.height,size=Number($('#grid-size').value);$('#grid').setAttribute('width',size);$('#grid').setAttribute('height',size);$('#grid path').setAttribute('d',`M${size} 0H0V${size}`);
 let s=`<rect x="8" y="9" width="${w}" height="${h}" rx="3" fill="#dce3dc"/><rect width="${w}" height="${h}" rx="3" fill="#fcfdfb" stroke="#b9c9be" stroke-width="1.5"/>`;
 if($('#grid-toggle').checked)s+=`<rect width="${w}" height="${h}" fill="url(#small-grid)"/><rect width="${w}" height="${h}" fill="url(#grid)"/>`;
 s+=`<g fill="#8b9c90" font-size="12" font-family="monospace"><text x="${w/2}" y="-24" text-anchor="middle">${w} mm</text><text transform="translate(-28 ${h/2}) rotate(-90)" text-anchor="middle">${h} mm</text></g><path d="M0 -12V-5M${w} -12V-5M0 -8H${w}M-12 0H-5M-12 ${h}H-5M-8 0V${h}" fill="none" stroke="#bacabd" stroke-width="1"/>`;
 for(const p of [...project.pieces].sort((a,b)=>(a.z||0)-(b.z||0)))s+=trackMarkup(byId[p.partId],p);
 const er=Math.max(3,view.w/Math.max(svg.clientWidth,1)*3);
 for(const e of getConnections().open)s+=`<circle data-endpoint="${esc(e.pieceId)}:${e.index}" class="endpoint" cx="${e.x}" cy="${e.y}" r="${er}" fill="#fff7e9" stroke="#ca9961" stroke-width="${er/3}"/>`;
 if(ghost&&placing)s+=`<g pointer-events="none">${trackMarkup(byId[ghost.partId],ghost,{ghost:true})}</g>`;
 if(!project.pieces.length)s+=`<text x="${w/2}" y="${h/2}" text-anchor="middle" fill="#a7b4aa" font-size="23">从左侧选择一段轨道</text><text x="${w/2}" y="${h/2+37}" text-anchor="middle" fill="#b2bdb5" font-size="15">点击画布放置 · 点击端点自动连接</text>`;
 if(gesture?.type==='box'&&gesture.moved){const r=selectionRect(gesture.start,gesture.end);s+=`<rect class="selection-box" x="${r.minX}" y="${r.minY}" width="${r.maxX-r.minX}" height="${r.maxY-r.minY}" fill="#295c49" fill-opacity=".12" stroke="#295c49" stroke-width="1.5" stroke-dasharray="5 3" vector-effect="non-scaling-stroke" pointer-events="none"/>`;}
 scene.innerHTML=s;$('#zoom-label').textContent=Math.round((project.board.width+240)/view.w*100)+'%';$('#canvas-name').textContent=project.name;$('#canvas-hint').textContent=placing?`${byId[placing.partId].label} · 点击放置 · R 旋转 · F 翻转 · Esc 退出`:tool==='pan'?'拖动画布平移 · 滚轮缩放':gesture?.type==='box'&&gesture.moved?`已选 ${selected.size} 段 · 完整框住轨道 · Esc 取消`:'空白处拖动框选 · Shift 追加 · 空格平移';svg.style.cursor=placing||gesture?.type==='box'?'crosshair':tool==='pan'||space?'grab':'default';}
function renderInspector(){const p=project.pieces.find(p=>selected.has(p.id)),part=p&&byId[p.partId];$('#board-width').value=project.board.width;$('#board-height').value=project.board.height;$('#project-name').value=project.name;
 if(p){const g=geometry(part,p),grade=g.paths[0]?.length?((p.zEnd-p.z)/g.paths[0].length*100):0;$('#selection-panel').innerHTML=`<div class="section-heading"><h2>零件属性</h2><span class="badge">${selected.size>1?`已选 ${selected.size} 段`:part.brand}</span></div><div class="part-title">${esc(part.label)}</div><div class="part-subtitle">${esc(part.sku)} · ${part.scale} 轨<br>${esc(part.name)}</div><div class="specs"><span>路径长度 <b>${g.length.toFixed(1)} mm</b></span><span>坡度 <b>${grade.toFixed(2)}%</b></span></div><div class="two-fields"><label>X / mm<input id="prop-x" type="number" step="0.1" value="${p.x.toFixed(2)}"></label><label>Y / mm<input id="prop-y" type="number" step="0.1" value="${p.y.toFixed(2)}"></label><label>旋转 / °<input id="prop-angle" type="number" step="1" value="${p.angle.toFixed(2)}"></label><label>起点高度 / mm<input id="prop-z" type="number" value="${p.z||0}"></label><label>终点高度 / mm<input id="prop-zEnd" type="number" value="${p.zEnd||0}"></label>${part.geometry.minLength?`<label>长度 / mm<input id="prop-length" type="number" min="${part.geometry.minLength}" max="${part.geometry.maxLength}" value="${p.length??part.geometry.length}"></label>`:''}</div>${part.geometry.type==='turntable'?`<label class="field">桥轨角度 / °<input id="prop-tableAngle" type="number" step="${part.geometry.step}" value="${p.tableAngle||0}"></label>`:''}${part.geometry.type==='flex'?`<label class="field">弯曲角度 / °（−180 到 180）<input id="prop-bend" type="number" min="-180" max="180" value="${p.bend||0}"></label>`:''}${part.notes?.length?`<div class="warnings">${part.notes.map(esc).join('<br>')}</div>`:''}${part.geometrySource?`<a class="source-link" href="${esc(part.geometrySource)}" target="_blank" rel="noopener">几何参数来源 ↗</a>`:''}<a class="source-link" href="${esc(part.source)}" target="_blank" rel="noopener">查看官方产品资料 ↗</a><button id="attach-btn" class="full-btn">以此零件继续接轨</button>`;
 for(const k of ['x','y','angle','z','zEnd','length','bend','tableAngle']){const el=$('#prop-'+k);if(el)el.onchange=()=>{const n=Number(el.value);if(!Number.isFinite(n)||Math.abs(n)>100000||(['z','zEnd'].includes(k)&&Math.abs(n)>10000)||(k==='bend'&&Math.abs(n)>180)||(k==='length'&&(n<part.geometry.minLength||n>part.geometry.maxLength))){toast('请输入有效范围内的数值');renderInspector();return;}record();p[k]=k==='angle'?norm(n):n;changed();};}
 $('#attach-btn').onclick=()=>{placing={partId:p.partId,angle:p.angle,flip:p.flip};tool='select';renderLibrary();renderCanvas();};
 }else{$('#selection-panel').innerHTML='<div class="section-heading"><h2>零件属性</h2><span class="badge">未选择</span></div><div class="empty-selection"><span>⌖</span><p>点击画布上的轨道<br>查看尺寸与位置</p></div>';}
 const length=project.pieces.reduce((n,p)=>n+geometry(byId[p.partId],p).length,0);$('#total-length').textContent=(length/1000).toFixed(2);$('#total-parts').textContent=project.pieces.length;$('#piece-count').textContent=project.pieces.length+' 段轨道';const c=getConnections();$('#connection-status').textContent=`${c.pairs.length} 处连接 · ${c.open.length} 个开放端点`;const b=bounds(project.pieces,byId),issues=[];if(b&&(b.minX<0||b.minY<0||b.maxX>project.board.width||b.maxY>project.board.height))issues.push('部分轨道中心线超出沙盘边界');const approx=project.pieces.filter(p=>byId[p.partId].status==='approximate').length;if(approx)issues.push(`${approx} 段使用示意尺寸，需复核`);if(new Set(project.pieces.map(p=>byId[p.partId].scale)).size>1)issues.push('布局含多种轨距，不能相互连接');$('#warnings').innerHTML=issues.map(s=>'<div>△ '+esc(s)+'</div>').join('');$('#undo-btn').disabled=!history.length;$('#redo-btn').disabled=!future.length;['delete','duplicate'].forEach(id=>$('#'+id+'-btn').disabled=!selected.size);$('#rotate-btn').disabled=!selected.size&&!placing;$('#flip-btn').disabled=!selected.size&&!placing;
 const bom=billOfMaterials(project.pieces,byId);$('#bom-panel').innerHTML=`<section><div class="section-heading"><h2>采购零件清单</h2><span class="badge">${bom.length} 款</span></div><p class="bom-summary">共 ${project.pieces.length} 段轨道。数量按实际轨道段计，同一包装内的变体合并到产品编号；购买包装数请核对官方说明。</p><button id="bom-export" class="full-btn">导出 CSV 清单 ↗</button>${bom.map(r=>`<div class="bom-row"><span>${esc(r.brand)} · ${esc(r.sku)}<small>${esc(r.name)}</small></span><b>${r.count}</b></div>`).join('')||'<div class="no-results">放置轨道后自动生成</div>'}</section>`;$('#bom-export').onclick=exportCSV;
}
function render(){renderCanvas();renderInspector();$('#select-tool').classList.toggle('active',tool==='select');$('#pan-tool').classList.toggle('active',tool==='pan');}
function setTool(t){tool=t;placing=null;ghost=null;renderLibrary();render();}
function beginPart(id){const p=byId[id];if(!p.geometry.type){modal(p.sku+' · 几何待核实',`<p>${esc(p.name)}</p><p>此产品已收录，但官方公开资料尚不足以建立准确的完整几何，当前不能放置。</p><a href="${esc(p.source)}" target="_blank" rel="noopener">打开官方资料 ↗</a>`);return;}placing={partId:id,angle:0,flip:1};selected.clear();tool='select';updateGhost(pointer);renderLibrary();render();if(p.status==='approximate')toast('此零件为名义尺寸示意，详情中可查看官方来源。');}
function candidate(at){let p={id:'preview',partId:placing.partId,x:at.x,y:at.y,angle:placing.angle,flip:placing.flip,z:0,zEnd:0};if($('#snap-toggle').checked){const snap=nearestSnap(byId[p.partId],p,getConnections().open,view.w/svg.clientWidth*20);if(snap)p=snap.piece;}return p;}
function updateGhost(at){if(placing)ghost=candidate(at);}
function place(at,endpointKey){if(!placing)return;if(project.pieces.length>=5000){toast('单个方案最多 5000 段轨道');return;}let p=candidate(at);if(endpointKey){const target=getConnections().open.find(e=>e.pieceId+':'+e.index===endpointKey);if(target){const part=byId[p.partId];if(part.brand!==target.brand||part.scale!==target.scale||(part.geometry.type==='flex'?'bare':'standard')!==(target.connector||'standard')){toast('不同品牌或轨距不能直接连接；需专用转换轨。');return;}p=snapToEndpoint(part,p,0,target);}}
 record();p.id=uid();project.pieces.push(p);selected.clear();selected.add(p.id);placing.angle=p.angle;placing.flip=p.flip;ghost=null;changed();}
function mutateSelection(fn){if(!selected.size)return;record();for(const p of project.pieces)if(selected.has(p.id))fn(p);changed();}
function rotate(delta=15){if(placing){placing.angle=norm(placing.angle+delta);updateGhost(pointer);renderCanvas();}else mutateSelection(p=>p.angle=norm(p.angle+delta));}
function flip(){if(placing){placing.flip*=-1;updateGhost(pointer);renderCanvas();}else mutateSelection(p=>p.flip*=-1);}
function remove(){if(!selected.size)return;record();project.pieces=project.pieces.filter(p=>!selected.has(p.id));selected.clear();changed();}
function duplicate(){if(!selected.size)return;record();const copy=project.pieces.filter(p=>selected.has(p.id)).map(p=>({...p,id:uid(),x:p.x+30,y:p.y+30}));project.pieces.push(...copy);selected.clear();copy.forEach(p=>selected.add(p.id));changed();}
function download(data,type,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const filename=()=>project.name.replace(/[\\/:*?"<>|]/g,'-')||'layout';
function exportCSV(){const q=s=>'"'+String(s).replace(/"/g,'""')+'"';const rows=[['品牌','轨距','产品编号','产品名称','所需轨道段数','官方来源'],...billOfMaterials(project.pieces,byId).map(r=>[r.brand,r.scale,r.sku,r.name,r.count,r.source])];download('\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8',filename()+'-零件清单.csv');toast('零件清单已导出');}
function exportSVG(){const w=project.board.width,h=project.board.height;const data=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}mm" height="${h}mm" viewBox="0 0 ${w} ${h}"><title>${esc(project.name)}</title><desc>Rail Studio; millimetres; 1:1 model dimensions. Nominal geometry requires verification.</desc><rect width="${w}" height="${h}" fill="white" stroke="#bdcbbf"/>${project.pieces.map(p=>trackMarkup(byId[p.partId],p,{export:true,labels:$('#labels-toggle').checked})).join('')}</svg>`;download(data,'image/svg+xml',filename()+'.svg');toast('已导出毫米尺寸 SVG 图纸');}
function replaceProject(next){record();project=next;selected.clear();placing=null;ghost=null;changed();renderLibrary();fit();}
function confirmReplace(title,fn){modal(title,'<p>当前方案会被替换。可先保存方案文件；替换后也可以撤销。</p><div class="modal-actions"><button id="confirm-save">先保存</button><button id="confirm-replace" class="primary">继续</button></div>');$('#confirm-save').onclick=()=>$('#save-btn').click();$('#confirm-replace').onclick=()=>{$('#modal').close();fn();};}
function showInfo(){const groups=['KATO','TOMIX'].map(b=>{const ps=catalog.parts.filter(p=>p.brand===b);return `<tr><td>${b}</td><td>${ps.length}</td><td>${ps.filter(p=>p.geometry.type).length}</td></tr>`;}).join('');modal('轨道库 · 来源与覆盖范围',`<p>${esc(catalog.scope)}</p><table style="width:100%;text-align:left"><thead><tr><th>品牌</th><th>目录条目</th><th>可放置</th></tr></thead><tbody>${groups}</tbody></table><p style="margin-top:16px">当前 ${catalog.parts.length} 个条目：${catalog.counts.dimensions} 个尺寸建模，${catalog.counts.library||0} 个开源几何，${catalog.counts.approximate} 个示意几何，${catalog.counts.pending} 个待核实。<br>更新于 ${esc(catalog.retrieved)}。目录按官方产品编号整理，同一包装的不同长度或角度拆分为独立轨道。</p><p><b>尺寸建模</b>：按已公布的长度、半径、角度绘制。<br><b>开源参数</b>：复杂零件采用 XTrackCAD 的显式路径与端点，并保留来源。<br><b>示意尺寸</b>：存在未核实几何或参数偏差。<br><b>待核实几何</b>：可查目录，暂不可放置。</p><p>平面检查不代表完整施工审核：车体扫掠、净空、真实超高、电气隔离和道床兼容性仍须结合实物确认。N 轨距为 9 mm，HO 轨距为 16.5 mm。</p><p><a href="https://www.tomytec.co.jp/tomix/products/info/?category_child=rail" target="_blank" rel="noopener">TOMIX 官方目录 ↗</a><br><a href="https://unitrack.katomodels.com/products/line_single" target="_blank" rel="noopener">KATO 官方目录 ↗</a></p><p>含 XTrackCAD 参数数据，作者 Dwyane Ward、Dave Bullis 等。转换日期：2026-09-26。<a href="./licenses/COPYING" target="_blank">GPL-2.0 许可</a> · <a href="./rail-studio-source.zip" download>源代码与原始参数</a></p>`);}
function help(){modal('操作指南',`<p><b>放置与接轨</b><br>在左侧选择轨道，点击画布放置。点击橙色开放端点会自动对齐新轨道。吸附只连接同品牌、同轨距、同高度的端点。</p><p><b>编辑</b><br>V 选择 · H 或按住空格平移 · R 旋转 15° · F 翻转<br>在空白处按住鼠标左键拖动，完整框住轨道即可多选；Shift + 框选追加，Shift + 点击增减选择。拖动任意已选轨道可整体移动。Esc 取消正在进行的拖动。<br>Delete 删除 · ⌘/Ctrl + D 复制<br>⌘/Ctrl + Z 撤销 · ⌘/Ctrl + Shift + Z 重做 · Esc 退出放置</p><p><b>保存与导出</b><br>当前方案自动保存在此浏览器。保存方案可下载 JSON，供备份或在其他设备打开。图纸为带真实毫米尺寸的 SVG，可用浏览器或矢量软件打印。</p><button id="show-mobile-inspector" class="full-btn">打开 / 关闭属性与零件清单</button>`);$('#show-mobile-inspector').onclick=()=>{$('.inspector').classList.toggle('mobile-open');$('#modal').close();};}
function setup(){
 window.addEventListener('pagehide',()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(project));}catch{}});
 $('#parts-list').onclick=e=>{const b=e.target.closest('[data-part]');if(b)beginPart(b.dataset.part);};$('#categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;renderLibrary();}};$$('[data-brand]').forEach(b=>b.onclick=()=>{brand=b.dataset.brand;category='全部';renderLibrary();});$('#scale-filter').onchange=e=>{scale=e.target.value;renderLibrary();};$('#search').oninput=renderLibrary;$('#usable-only').onchange=renderLibrary;
 $('#select-tool').onclick=()=>setTool('select');$('#pan-tool').onclick=()=>setTool('pan');$('#undo-btn').onclick=undo;$('#redo-btn').onclick=redo;$('#rotate-btn').onclick=()=>rotate();$('#flip-btn').onclick=flip;$('#duplicate-btn').onclick=duplicate;$('#delete-btn').onclick=remove;$('#zoom-in').onclick=()=>zoom(.8);$('#zoom-out').onclick=()=>zoom(1.25);$('#fit-btn').onclick=fit;$('#help-btn').onclick=help;$('#inspector-toggle').onclick=()=>$('.inspector').classList.toggle('mobile-open');$('#catalog-info').onclick=showInfo;$('#modal-close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
 for(const id of ['grid-size','grid-toggle','labels-toggle'])$('#'+id).onchange=renderCanvas;
 for(const [id,k] of [['board-width','width'],['board-height','height']])$('#'+id).onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||n<100||n>50000){toast('沙盘尺寸应在 100–50000 mm 之间');renderInspector();return;}record();project.board[k]=n;changed();fit();};
 $('#project-name').onchange=e=>{record();project.name=e.target.value.trim().slice(0,160)||'未命名沙盘';changed();};
 $('#save-btn').onclick=()=>{download(JSON.stringify(project,null,2),'application/json',filename()+'.rail.json');toast('方案文件已保存');};$('#new-btn').onclick=()=>confirmReplace('新建沙盘',()=>replaceProject({version:1,name:'未命名沙盘',board:{width:1800,height:1000},pieces:[]}));$('#demo-btn').onclick=()=>confirmReplace('载入双环线示例',()=>replaceProject(demoProject(byId)));$('#open-btn').onclick=()=>$('#file-input').click();$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('方案文件不能超过 5 MB');const next=validateProject(JSON.parse(await file.text()),byId);confirmReplace('打开 '+next.name,()=>{replaceProject(next);toast('方案已打开');});}catch(error){toast('无法打开：'+error.message);}e.target.value='';};
 $('#export-btn').onclick=()=>{modal('导出设计',`<div class="export-options"><button id="export-svg"><b>SVG 矢量图纸 ↗</b><small>保留毫米尺寸，可编辑、打印；当前标签设置也会导出。</small></button><button id="export-csv"><b>CSV 零件清单 ↗</b><small>按品牌与产品编号合并，可用 Excel 打开。</small></button></div>`);$('#export-svg').onclick=exportSVG;$('#export-csv').onclick=exportCSV;};
 $('#check-btn').onclick=()=>{const c=getConnections(),b=bounds(project.pieces,byId);modal('布局检查',`<p><b>${project.pieces.length} 段轨道 · ${c.pairs.length} 处连接 · ${c.open.length} 个开放端点</b></p><p>端点连接要求：间隙 ≤ 0.6 mm、方向误差 &lt; 0.6°、高度差 &lt; 0.5 mm，且品牌与轨距相同。</p><p>${b?`中心线占用范围：${(b.maxX-b.minX).toFixed(1)} × ${(b.maxY-b.minY).toFixed(1)} mm。`:'当前没有轨道。'}</p><p>${esc($('#warnings').textContent)||'中心线位于沙盘边界内。'}</p><p>开放端点可能是预留支线，并非一定是错误。此检查尚不涵盖车体净空、道床碰撞与电路。</p>`);};
 $$('[data-panel]').forEach(b=>b.onclick=()=>{$$('[data-panel]').forEach(x=>x.classList.toggle('active',x===b));$('#design-panel').hidden=b.dataset.panel!=='design';$('#bom-panel').hidden=b.dataset.panel!=='bom';});
 svg.addEventListener('wheel',e=>{e.preventDefault();if(!gesture)zoom(Math.exp(e.deltaY*.001),point(e));},{passive:false});
 svg.addEventListener('pointerdown',e=>{if(gesture||e.isPrimary===false||(e.button!==0&&e.button!==1))return;e.preventDefault();svg.focus({preventScroll:true});const at=point(e);pointer=at;const ep=e.target.closest('[data-endpoint]')?.dataset.endpoint,pid=e.target.closest('[data-piece]')?.dataset.piece;
 if(tool==='pan'||space||e.button===1){gesture={type:'pan',pointerId:e.pointerId,start:at,view:{...view},client:{x:e.clientX,y:e.clientY}};svg.setPointerCapture(e.pointerId);return;}
 if(placing){place(at,ep);return;}
 if(pid||ep){const id=pid||ep.slice(0,ep.lastIndexOf(':'));if(e.shiftKey){if(selected.has(id))selected.delete(id);else selected.add(id);}else if(!selected.has(id)){selected.clear();selected.add(id);}gesture={type:'move',pointerId:e.pointerId,start:at,before:clone(project),original:project.pieces.filter(p=>selected.has(p.id)).map(p=>({...p})),moved:false};svg.setPointerCapture(e.pointerId);render();}
 else{gesture={type:'box',pointerId:e.pointerId,start:at,end:at,client:{x:e.clientX,y:e.clientY},beforeSelected:[...selected],additive:e.shiftKey,moved:false,items:project.pieces.map(p=>({id:p.id,bounds:bounds([p],byId)}))};if(!e.shiftKey)selected.clear();svg.setPointerCapture(e.pointerId);render();}
 });
 svg.addEventListener('pointermove',e=>{if(gesture&&e.pointerId!==gesture.pointerId)return;pointer=point(e);$('#position-status').textContent=`X ${pointer.x.toFixed(0)} · Y ${pointer.y.toFixed(0)} mm`;if(gesture?.type==='pan'){const r=svg.getBoundingClientRect();view.x=gesture.view.x-(e.clientX-gesture.client.x)*view.w/r.width;view.y=gesture.view.y-(e.clientY-gesture.client.y)*view.h/r.height;renderCanvas();return;}
 if(gesture?.type==='box'){updateBox(e);renderCanvas();return;}
 if(gesture?.type==='move'){const dx=pointer.x-gesture.start.x,dy=pointer.y-gesture.start.y;if(Math.hypot(dx,dy)<1&&!gesture.moved)return;gesture.moved=true;for(const orig of gesture.original){const p=project.pieces.find(p=>p.id===orig.id);p.x=orig.x+dx;p.y=orig.y+dy;p.angle=orig.angle;p.z=orig.z;p.zEnd=orig.zEnd;}
 if(gesture.original.length===1&&$('#snap-toggle').checked){const p=project.pieces.find(p=>selected.has(p.id)),others=project.pieces.filter(p=>!selected.has(p.id)),targets=connections(others,byId).open,s=nearestSnap(byId[p.partId],p,targets,view.w/svg.clientWidth*16);if(s)Object.assign(p,s.piece);}cache=null;renderCanvas();return;}
 updateGhost(pointer);if(placing)renderCanvas();});
 function updateBox(e){const g=gesture;if(Math.hypot(e.clientX-g.client.x,e.clientY-g.client.y)<4&&!g.moved)return;g.moved=true;g.end=point(e);const ids=boxedSelection(g.items,g.start,g.end,g.additive?g.beforeSelected:[]);selected.clear();ids.forEach(id=>selected.add(id));}
 const finish=e=>{if(!gesture||e.pointerId!==gesture.pointerId)return;if(gesture.type==='box')updateBox(e);if(gesture.type==='move'&&gesture.moved){history.push(gesture.before);if(history.length>80)history.shift();future=[];persist();cache=null;}gesture=null;if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);render();};
 const cancel=e=>{if(!gesture||(e?.pointerId!==undefined&&e.pointerId!==gesture.pointerId))return;const id=gesture.pointerId;if(gesture.before){project=gesture.before;cache=null;}if(gesture.type==='box'){selected.clear();gesture.beforeSelected.forEach(id=>selected.add(id));}gesture=null;if(svg.hasPointerCapture(id))svg.releasePointerCapture(id);render();};
 svg.addEventListener('pointerup',finish);svg.addEventListener('pointercancel',cancel);svg.addEventListener('lostpointercapture',cancel);svg.addEventListener('pointerleave',()=>{if(!gesture){ghost=null;renderCanvas();}});
 window.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('#modal').open)return;if(gesture){if(e.key==='Escape'){e.preventDefault();cancel();}return;}const mod=e.metaKey||e.ctrlKey;if(e.code==='Space'){e.preventDefault();space=true;svg.style.cursor='grab';return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}else if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();$('#save-btn').click();}else if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();project.pieces.forEach(p=>selected.add(p.id));render();}else if(e.key==='Escape'){placing=null;ghost=null;selected.clear();renderLibrary();render();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}else if(e.key.toLowerCase()==='r')rotate(e.shiftKey?-15:15);else if(e.key.toLowerCase()==='f')flip();else if(e.key.toLowerCase()==='v')setTool('select');else if(e.key.toLowerCase()==='h')setTool('pan');});window.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;renderCanvas();}});window.addEventListener('blur',()=>{space=false;cancel();});new ResizeObserver(()=>fit()).observe($('#canvas-wrap'));
}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const defs=[{name:'read_rail_layout',description:'Read the current rail layout, track catalog coverage, and bill of materials.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({project:clone(project),billOfMaterials:billOfMaterials(project.pieces,byId),catalogCounts:catalog.counts})},{name:'add_rail_pieces',description:'Place a batch of catalog track pieces in millimetres. Validates the whole batch before changing the visible layout.',inputSchema:{type:'object',properties:{pieces:{type:'array',minItems:1,maxItems:100,items:{type:'object',properties:{partId:{type:'string'},x:{type:'number'},y:{type:'number'},angle:{type:'number'},flip:{type:'number',enum:[1,-1]}},required:['partId','x','y','angle'],additionalProperties:false}}},required:['pieces'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Array.isArray(input?.pieces)||!input.pieces.length||input.pieces.length>100)throw Error('Expected 1–100 pieces');const added=input.pieces.map(p=>({...p,id:uid(),flip:p.flip??1,z:0,zEnd:0}));const next=validateProject({...project,pieces:[...project.pieces,...added]},byId);record();project=next;changed();return {added:added.map(p=>p.id),total:project.pieces.length};}}];for(const def of defs){try{Promise.resolve(context.registerTool(def,{signal:lifecycle.signal})).catch(console.warn);}catch(e){console.warn(e);}}}
try{const response=await fetch('./catalog.json');if(!response.ok)throw Error('轨道目录加载失败');catalog=await response.json();byId=Object.fromEntries(catalog.parts.map(p=>[p.id,p]));project=demoProject(byId);try{const saved=localStorage.getItem(STORAGE_KEY);if(saved)project=validateProject(JSON.parse(saved),byId);}catch{toast('本机旧方案无法读取，已载入示例；可打开备份文件。');}setup();renderLibrary();render();fit();registerTools();}catch(error){$('#parts-list').innerHTML=`<div class="no-results">${esc(error.message)}<br>请通过本地服务器或已发布网址打开应用。</div>`;$('#connection-status').textContent='加载失败';console.error(error);}
